INSERT dbo.Categories (Slug,Name,Domain)
SELECT j.Slug,
    j.Name,
    j.Domain FROM OPENJSON(@data,'$.categories') WITH (Slug nvarchar(80) '$.slug',Name nvarchar(100) '$.name',Domain nvarchar(20) '$.domain') j
WHERE NOT EXISTS (SELECT 1 FROM dbo.Categories t WHERE t.Slug=j.Slug);
INSERT dbo.Brands (Slug,Name,Country,IsDemo)
SELECT j.Slug,
    j.Name,
    j.Country,
    1 FROM OPENJSON(@data,'$.brands') WITH (Slug nvarchar(80) '$.slug',Name nvarchar(100) '$.name',Country nvarchar(100) '$.country') j
WHERE NOT EXISTS (SELECT 1 FROM dbo.Brands t WHERE t.Slug=j.Slug);
INSERT dbo.Profiles (Slug,Name,Kind)
SELECT j.Slug,
    j.Name,
    j.Kind FROM OPENJSON(@data,'$.profiles') WITH (Slug nvarchar(80) '$.slug',Name nvarchar(100) '$.name',Kind nvarchar(20) '$.kind') j
WHERE NOT EXISTS (SELECT 1 FROM dbo.Profiles t WHERE t.Slug=j.Slug);
INSERT dbo.Concerns (Slug,Name,Domain,SearchTerms)
SELECT j.Slug,
    j.Name,
    j.Domain,
    j.SearchTerms FROM OPENJSON(@data,'$.concerns') WITH (Slug nvarchar(80) '$.slug',Name nvarchar(100) '$.name',Domain nvarchar(20) '$.domain', SearchTerms nvarchar(500) '$.searchTerms') j
WHERE NOT EXISTS (SELECT 1 FROM dbo.Concerns t WHERE t.Slug=j.Slug);
INSERT dbo.Ingredients (Slug,Name,InciName)
SELECT j.Slug,
    j.Name,
    j.InciName FROM OPENJSON(@data,'$.ingredients') WITH (Slug nvarchar(80) '$.slug',Name nvarchar(100) '$.name',InciName nvarchar(200) '$.inciName') j
WHERE NOT EXISTS (SELECT 1 FROM dbo.Ingredients t WHERE t.Slug=j.Slug);

UPDATE c SET ParentId=p.Id FROM dbo.Categories c
JOIN OPENJSON(@data,
    '$.categories') WITH (Slug nvarchar(80) '$.slug',
    Parent nvarchar(80) '$.parent') j ON j.Slug=c.Slug
JOIN dbo.Categories p ON p.Slug=j.Parent WHERE c.ParentId IS NULL;

SELECT j.*,b.Id AS BrandId,c.Id AS CategoryId INTO #SeedProducts
FROM OPENJSON(@data,'$.products') WITH (
    Sku nvarchar(80) '$.sku',
        Name nvarchar(200) '$.name',
        BrandSlug nvarchar(80) '$.brandSlug',
        CategorySlug nvarchar(80) '$.categorySlug',
    Brand nvarchar(100) '$.brand',
        Category nvarchar(100) '$.category',
        SkinTypes nvarchar(300) '$.skinTypes',
        HairTypes nvarchar(300) '$.hairTypes',
    Concerns nvarchar(500) '$.concernsText',
        Ingredients nvarchar(max) '$.ingredientsText',
        Description nvarchar(max) '$.description',
    Warnings nvarchar(max) '$.warnings',
        UsageInstructions nvarchar(2000) '$.usageInstructions',
        SearchKeywords nvarchar(1000) '$.searchKeywords',
    Price decimal(18,2) '$.price',
        StockQuantity int '$.stockQuantity',
        IsActive bit '$.isActive',
        FragranceFree bit '$.fragranceFree',
    ProfileJson nvarchar(max) '$.profiles' AS JSON,ConcernJson nvarchar(max) '$.concerns' AS JSON,
    IngredientJson nvarchar(max) '$.ingredients' AS JSON,
        VariantJson nvarchar(max) '$.variants' AS JSON
) j JOIN dbo.Brands b ON b.Slug=j.BrandSlug JOIN dbo.Categories c ON c.Slug=j.CategorySlug;

INSERT dbo.Products (Sku,
    Name,
    Brand,
    Category,
    BrandId,
    CategoryId,
    SkinTypes,
    HairTypes,
    Concerns,
    Ingredients,
    Description,
    Warnings,
                     UsageInstructions,
                         SearchKeywords,
                         Price,
                         StockQuantity,
                         IsActive,
                         FragranceFree,
                         IsDemo,
                         Currency)
SELECT s.Sku,
    s.Name,
    s.Brand,
    s.Category,
    s.BrandId,
    s.CategoryId,
    s.SkinTypes,
    s.HairTypes,
    s.Concerns,
    s.Ingredients,
    s.Description,
    s.Warnings,
       s.UsageInstructions,
           s.SearchKeywords,
           s.Price,
           s.StockQuantity,
           s.IsActive,
           s.FragranceFree,
           1,
           'IRR'
FROM #SeedProducts s WHERE NOT EXISTS (SELECT 1 FROM dbo.Products p WHERE p.Sku=s.Sku);
UPDATE p SET FragranceFree=s.FragranceFree FROM dbo.Products p JOIN #SeedProducts s ON p.Sku=s.Sku
WHERE p.IsDemo=1 AND p.FragranceFree IS NULL;

INSERT dbo.ProductProfiles (ProductId,ProfileId)
SELECT p.Id,t.Id FROM #SeedProducts s JOIN dbo.Products p ON p.Sku=s.Sku
CROSS APPLY OPENJSON(s.ProfileJson) j JOIN dbo.Profiles t ON t.Slug=j.value
WHERE NOT EXISTS (SELECT 1 FROM dbo.ProductProfiles x WHERE x.ProductId=p.Id AND x.ProfileId=t.Id);

INSERT dbo.ProductConcerns (ProductId,ConcernId)
SELECT p.Id,t.Id FROM #SeedProducts s JOIN dbo.Products p ON p.Sku=s.Sku
CROSS APPLY OPENJSON(s.ConcernJson) j JOIN dbo.Concerns t ON t.Slug=j.value
WHERE NOT EXISTS (SELECT 1 FROM dbo.ProductConcerns x WHERE x.ProductId=p.Id AND x.ConcernId=t.Id);

INSERT dbo.ProductIngredients (ProductId,IngredientId)
SELECT p.Id,t.Id FROM #SeedProducts s JOIN dbo.Products p ON p.Sku=s.Sku
CROSS APPLY OPENJSON(s.IngredientJson) j JOIN dbo.Ingredients t ON t.Slug=j.value
WHERE NOT EXISTS (SELECT 1 FROM dbo.ProductIngredients x WHERE x.ProductId=p.Id AND x.IngredientId=t.Id);

INSERT dbo.ProductVariants (ProductId,
    Sku,
    Name,
    SizeValue,
    SizeUnit,
    Shade,
    Finish,
    Price,
    StockQuantity,
    IsActive)
SELECT p.Id,v.Sku,v.Name,v.SizeValue,v.SizeUnit,v.Shade,v.Finish,v.Price,v.StockQuantity,v.IsActive
FROM #SeedProducts s JOIN dbo.Products p ON p.Sku=s.Sku
CROSS APPLY OPENJSON(s.VariantJson) WITH (
    Sku nvarchar(100) '$.sku',
        Name nvarchar(200) '$.name',
        SizeValue decimal(10,2) '$.sizeValue',
        SizeUnit nvarchar(10) '$.sizeUnit',
    Shade nvarchar(100) '$.shade',
        Finish nvarchar(100) '$.finish',
        Price decimal(18,2) '$.price',
        StockQuantity int '$.stockQuantity',
        IsActive bit '$.isActive'
) v WHERE NOT EXISTS (SELECT 1 FROM dbo.ProductVariants x WHERE x.Sku=v.Sku);

-- Associate the three legacy sample products without changing their descriptive fields.
UPDATE p SET CategoryId=c.Id FROM dbo.Products p JOIN dbo.Categories c ON c.Slug='face-moisturizer'
WHERE p.CategoryId IS NULL AND p.Category=N'مرطوب‌کننده';
UPDATE p SET CategoryId=c.Id FROM dbo.Products p JOIN dbo.Categories c ON c.Slug='gentle-cleanser'
WHERE p.CategoryId IS NULL AND p.Category=N'شوینده';
IF NOT EXISTS (SELECT 1 FROM dbo.Brands WHERE Slug='legacy-sample')
INSERT dbo.Brands (Slug,Name,IsDemo) VALUES ('legacy-sample',N'برند نمونه',1);
UPDATE p SET BrandId=b.Id FROM dbo.Products p JOIN dbo.Brands b ON b.Slug='legacy-sample'
WHERE p.BrandId IS NULL AND p.Brand=N'برند نمونه';
-- Label only the original known sample rows, never unrelated products.
UPDATE dbo.Products SET IsDemo=1 WHERE Id IN (1,2,3) AND Brand=N'برند نمونه'
AND Name IN (N'مرطوب‌کننده سبک صورت',N'شوینده ملایم صورت',N'کرم مرطوب‌کننده پوست خشک');
COMMIT TRANSACTION;
SELECT COUNT(*) AS TotalProducts,SUM(CAST(IsDemo AS int)) AS DemoProducts FROM dbo.Products;
SELECT COUNT(*) AS TotalVariants FROM dbo.ProductVariants;
